-- ============================================================
-- AI MARKET INTELLIGENCE PLATFORM
-- PostgreSQL Schema
--
-- IDENTITY vs SERIAL:
--
-- SERIAL:
-- - Ancienne syntaxe PostgreSQL.
-- - Crée automatiquement une séquence séparée.
-- - Fonctionne toujours, mais est moins explicite.
--
-- IDENTITY:
-- - Syntaxe SQL moderne et standard.
-- - Recommandée pour les nouveaux projets PostgreSQL.
-- - GENERATED BY DEFAULT permet également de fournir
--   manuellement un ID si nécessaire.
--
-- Ce schéma utilise donc :
--
-- INTEGER GENERATED BY DEFAULT AS IDENTITY
-- ============================================================


-- ============================================================
-- DROP EXISTING TABLES
--
-- Ordre inverse des dépendances.
-- CASCADE supprime également les contraintes dépendantes.
-- ============================================================

DROP TABLE IF EXISTS portfolio_strategist_runs CASCADE;
DROP TABLE IF EXISTS market_opportunity_events CASCADE;
DROP TABLE IF EXISTS portfolio_strategists CASCADE;
-- Compatibility cleanup for the short-lived first demo name.
DROP TABLE IF EXISTS portfolio_guardian_runs CASCADE;
DROP TABLE IF EXISTS portfolio_guardians CASCADE;
DROP TABLE IF EXISTS orchestrator_analysis_jobs CASCADE;
DROP TABLE IF EXISTS signals CASCADE;
DROP TABLE IF EXISTS analysis_inputs CASCADE;
DROP TABLE IF EXISTS analysis_sources CASCADE;
DROP TABLE IF EXISTS analysis_assets CASCADE;
DROP TABLE IF EXISTS analyses CASCADE;

DROP TABLE IF EXISTS classification_niches CASCADE;
DROP TABLE IF EXISTS classification_assets CASCADE;
DROP TABLE IF EXISTS source_classifications CASCADE;

DROP TABLE IF EXISTS asset_niches CASCADE;
DROP TABLE IF EXISTS niches CASCADE;

DROP TABLE IF EXISTS data_sources CASCADE;
DROP TABLE IF EXISTS market_data CASCADE;
DROP TABLE IF EXISTS rss_feed_runs CASCADE;
DROP TABLE IF EXISTS rss_feeds CASCADE;

DROP TABLE IF EXISTS prompts CASCADE;

DROP TABLE IF EXISTS transactions CASCADE;
DROP TABLE IF EXISTS portfolio_assets CASCADE;
DROP TABLE IF EXISTS portfolios CASCADE;

DROP TABLE IF EXISTS favorites CASCADE;

DROP TABLE IF EXISTS futures CASCADE;
DROP TABLE IF EXISTS commodities CASCADE;
DROP TABLE IF EXISTS forex CASCADE;
DROP TABLE IF EXISTS crypto CASCADE;
DROP TABLE IF EXISTS stocks CASCADE;

DROP TABLE IF EXISTS assets CASCADE;
DROP TABLE IF EXISTS users CASCADE;

-- ============================================================
-- UTILISATEURS
-- ============================================================

CREATE TABLE users (
    usr_id INTEGER GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,

    usr_username VARCHAR NOT NULL UNIQUE,
    usr_email VARCHAR NOT NULL UNIQUE,
    usr_password_hash VARCHAR NOT NULL,

    usr_is_active BOOLEAN NOT NULL DEFAULT TRUE,
    usr_created_at TIMESTAMP NOT NULL DEFAULT NOW(),
    usr_role VARCHAR NOT NULL DEFAULT 'employe'

);


-- ============================================================
-- ACTIFS
-- ============================================================

CREATE TABLE assets (
    ast_id INTEGER GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,

    -- Identité Yahoo Finance de l'actif.
    ast_symbol VARCHAR NOT NULL UNIQUE,
    ast_name VARCHAR NOT NULL,

    -- Type normalisé utilisé par FAAH.
    ast_type VARCHAR NOT NULL,

    -- Type original retourné par Yahoo Finance.
    ast_yahoo_type VARCHAR,

    -- Informations générales de négociation.
    ast_exchange VARCHAR,
    ast_currency VARCHAR,
    ast_country VARCHAR,
    ast_logo BYTEA,
    ast_logo_mime_type VARCHAR,
    ast_logo_last_attempt_at TIMESTAMPTZ,

    -- Indique si le marché en direct doit suivre cet actif.
    ast_is_tracked BOOLEAN NOT NULL DEFAULT FALSE,

    ast_created_at TIMESTAMPTZ NOT NULL DEFAULT NOW(),
    ast_updated_at TIMESTAMPTZ NOT NULL DEFAULT NOW(),

    CONSTRAINT chk_asset_type
        CHECK (
            ast_type IN (
                'stock',
                'crypto',
                'forex',
                'future'
            )
        )
);


-- ============================================================
-- FAVORIS
-- ============================================================

CREATE TABLE favorites (
    fav_usr_id INTEGER NOT NULL,
    fav_ast_id INTEGER NOT NULL,

    fav_created_at TIMESTAMP NOT NULL DEFAULT NOW(),

    PRIMARY KEY (
        fav_usr_id,
        fav_ast_id
    ),

    CONSTRAINT fk_favorites_user
        FOREIGN KEY (fav_usr_id)
        REFERENCES users(usr_id),

    CONSTRAINT fk_favorites_asset
        FOREIGN KEY (fav_ast_id)
        REFERENCES assets(ast_id)
);


-- ============================================================
-- ACTIONS
-- ============================================================

CREATE TABLE stocks (
    sto_ast_id INTEGER PRIMARY KEY,

    sto_sector VARCHAR,
    sto_industry VARCHAR,

    CONSTRAINT fk_stocks_asset
        FOREIGN KEY (sto_ast_id)
        REFERENCES assets(ast_id)
        ON DELETE CASCADE
);


-- ============================================================
-- CRYPTOMONNAIES
-- ============================================================

CREATE TABLE crypto (
    cry_ast_id INTEGER PRIMARY KEY,

    cry_base_currency VARCHAR,
    cry_quote_currency VARCHAR,

    cry_blockchain VARCHAR,
    cry_contract_address VARCHAR,

    CONSTRAINT fk_crypto_asset
        FOREIGN KEY (cry_ast_id)
        REFERENCES assets(ast_id)
        ON DELETE CASCADE
);


-- ============================================================
-- FOREX
-- ============================================================

CREATE TABLE forex (
    for_ast_id INTEGER PRIMARY KEY,

    for_base_currency VARCHAR NOT NULL,
    for_quote_currency VARCHAR NOT NULL,

    CONSTRAINT fk_forex_asset
        FOREIGN KEY (for_ast_id)
        REFERENCES assets(ast_id)
        ON DELETE CASCADE
);


-- ============================================================
-- MATIÈRES PREMIÈRES
-- ============================================================

CREATE TABLE futures (
    fut_ast_id INTEGER PRIMARY KEY,

    -- Actif sous-jacent, par exemple Or ou Pétrole WTI.
    fut_underlying_name VARCHAR,

    -- Type du sous-jacent : matière première, devise,
    -- indice ou taux d'intérêt.
    fut_underlying_type VARCHAR,

    fut_unit VARCHAR,
    fut_contract_size DECIMAL(18,2),

    CONSTRAINT fk_futures_asset
        FOREIGN KEY (fut_ast_id)
        REFERENCES assets(ast_id)
        ON DELETE CASCADE
);

