-- ============================================================
-- NICHES ASSETS
-- ============================================================

CREATE TABLE asset_niches (
    ani_ast_id INTEGER NOT NULL,
    ani_nic_id INTEGER NOT NULL,
    ani_prm_id INTEGER,

    PRIMARY KEY (
        ani_ast_id,
        ani_nic_id
    ),

    CONSTRAINT fk_asset_niches_asset
        FOREIGN KEY (ani_ast_id)
        REFERENCES assets(ast_id)
        ON DELETE CASCADE,

    CONSTRAINT fk_asset_niches_niche
        FOREIGN KEY (ani_nic_id)
        REFERENCES niches(nic_id)
        ON DELETE CASCADE
);

-- ============================================================
-- PORTEFEUILLES
-- ============================================================

CREATE TABLE portfolios (
    prt_id INTEGER GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,

    -- Un utilisateur possède un seul portefeuille.
    prt_usr_id INTEGER NOT NULL UNIQUE,

    prt_name VARCHAR NOT NULL,
    prt_description TEXT,

    prt_strategy_type VARCHAR,
    prt_risk_tolerance VARCHAR DEFAULT 'medium',

    prt_max_position_size_pct DECIMAL(5,2) DEFAULT 5.00,
    prt_max_open_positions INTEGER DEFAULT 10,

    prt_base_currency VARCHAR DEFAULT 'USD',

    prt_is_active BOOLEAN DEFAULT TRUE,

    prt_created_at TIMESTAMP NOT NULL DEFAULT NOW(),
    prt_updated_at TIMESTAMP NOT NULL DEFAULT NOW(),

    CONSTRAINT fk_portfolios_user
        FOREIGN KEY (prt_usr_id)
        REFERENCES users(usr_id)
);


-- ============================================================
-- ACTIFS DU PORTEFEUILLE
-- ============================================================

CREATE TABLE portfolio_assets (
    pas_prt_id INTEGER NOT NULL,
    pas_ast_id INTEGER NOT NULL,

    pas_quantity DECIMAL(18,8) NOT NULL DEFAULT 0,
    pas_average_purchase_price DECIMAL(18,8) NOT NULL DEFAULT 0,

    pas_is_active BOOLEAN NOT NULL DEFAULT TRUE,
    pas_created_at TIMESTAMP NOT NULL DEFAULT NOW(),
    pas_updated_at TIMESTAMP NOT NULL DEFAULT NOW(),

    PRIMARY KEY (
        pas_prt_id,
        pas_ast_id
    ),

    CONSTRAINT fk_portfolio_assets_portfolio
        FOREIGN KEY (pas_prt_id)
        REFERENCES portfolios(prt_id),

    CONSTRAINT fk_portfolio_assets_asset
        FOREIGN KEY (pas_ast_id)
        REFERENCES assets(ast_id)
);


-- ============================================================
-- TRANSACTIONS
-- Une ligne est créée seulement lors d'un achat ou d'une vente.
-- ============================================================

CREATE TABLE transactions (
    id_trans INTEGER GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,

    prt_id_trans INTEGER NOT NULL,
    ast_id_trans INTEGER NOT NULL,

    type_trans VARCHAR(10) NOT NULL
        CHECK (type_trans IN ('buy', 'sell')),
    quantity_trans NUMERIC(18,8) NOT NULL
        CHECK (quantity_trans > 0),
    price_trans NUMERIC(18,8) NOT NULL
        CHECK (price_trans > 0),
    fees_trans NUMERIC(18,8) NOT NULL DEFAULT 0
        CHECK (fees_trans >= 0),
    currency_trans VARCHAR(10) NOT NULL DEFAULT 'USD'
        CHECK (currency_trans = 'USD'),
    "createdAt_trans" TIMESTAMPTZ NOT NULL DEFAULT NOW(),

    CONSTRAINT fk_transactions_portfolio
        FOREIGN KEY (prt_id_trans)
        REFERENCES portfolios(prt_id),

    CONSTRAINT fk_transactions_asset
        FOREIGN KEY (ast_id_trans)
        REFERENCES assets(ast_id)
);


-- ============================================================
-- PROMPTS
-- ============================================================

CREATE TABLE prompts (
    prm_id INTEGER GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,

    prm_name VARCHAR NOT NULL,
    prm_type VARCHAR NOT NULL,

    prm_version INTEGER DEFAULT 1,

    prm_prompt_text TEXT NOT NULL,

    prm_is_active BOOLEAN DEFAULT TRUE,

    prm_created_at TIMESTAMP NOT NULL DEFAULT NOW(),
    prm_updated_at TIMESTAMP NOT NULL DEFAULT NOW()
);

ALTER TABLE asset_niches
    ADD CONSTRAINT fk_asset_niches_prompt
    FOREIGN KEY (ani_prm_id)
    REFERENCES prompts(prm_id)
    ON DELETE SET NULL;


-- ============================================================
-- FLUX RSS ET ÉTAT DU PLANIFICATEUR
-- PostgreSQL est la source de vérité pour la configuration et le planning.
-- ============================================================

CREATE TABLE rss_feeds (
    rsf_id INTEGER GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
    rsf_name VARCHAR NOT NULL UNIQUE,
    rsf_url TEXT NOT NULL,
    rsf_source_prefix VARCHAR NOT NULL,
    rsf_poll_interval_seconds INTEGER NOT NULL DEFAULT 3600,
    rsf_status VARCHAR NOT NULL DEFAULT 'active',
    rsf_last_polled_at TIMESTAMPTZ,
    rsf_next_poll_at TIMESTAMPTZ,
    rsf_next_poll_trigger VARCHAR NOT NULL DEFAULT 'schedule',
    rsf_pending_instruction_id VARCHAR,
    rsf_last_status VARCHAR,
    rsf_last_items_processed INTEGER NOT NULL DEFAULT 0,
    rsf_last_error TEXT,
    rsf_created_at TIMESTAMPTZ NOT NULL DEFAULT NOW(),
    rsf_updated_at TIMESTAMPTZ NOT NULL DEFAULT NOW(),

    CONSTRAINT chk_rss_feed_poll_interval
        CHECK (rsf_poll_interval_seconds BETWEEN 300 AND 7200),
    CONSTRAINT chk_rss_feed_status
        CHECK (rsf_status IN ('active', 'paused')),
    CONSTRAINT chk_rss_feed_next_trigger
        CHECK (rsf_next_poll_trigger IN ('schedule', 'run_now'))
);

CREATE INDEX idx_rss_feeds_due
    ON rss_feeds (rsf_status, rsf_next_poll_at);

CREATE TABLE rss_feed_runs (
    rfr_id INTEGER GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
    rfr_rsf_id INTEGER NOT NULL,
    rfr_trigger VARCHAR NOT NULL,
    rfr_instruction_id VARCHAR,
    rfr_status VARCHAR NOT NULL,
    rfr_started_at TIMESTAMPTZ NOT NULL DEFAULT NOW(),
    rfr_completed_at TIMESTAMPTZ,
    rfr_items_processed INTEGER NOT NULL DEFAULT 0,
    rfr_error TEXT,

    CONSTRAINT fk_rss_feed_runs_feed
        FOREIGN KEY (rfr_rsf_id)
        REFERENCES rss_feeds(rsf_id)
        ON DELETE CASCADE,
    CONSTRAINT chk_rss_feed_run_trigger
        CHECK (rfr_trigger IN ('schedule', 'run_now')),
    CONSTRAINT chk_rss_feed_run_status
        CHECK (rfr_status IN ('running', 'succeeded', 'failed'))
);

CREATE INDEX idx_rss_feed_runs_feed_started
    ON rss_feed_runs (rfr_rsf_id, rfr_started_at DESC);

