-- ============================================================
-- SOURCES DE DONNÉES
-- ============================================================

CREATE TABLE data_sources (
    src_id INTEGER GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,

    src_type VARCHAR NOT NULL,

    src_title TEXT,

    src_original_url VARCHAR,
    src_storage_path VARCHAR,
	src_content TEXT,
    src_published_at TIMESTAMP,

    src_is_processed BOOLEAN NOT NULL DEFAULT FALSE,

    src_created_at TIMESTAMP NOT NULL DEFAULT NOW()
);


-- ============================================================
-- CLASSIFICATIONS DES SOURCES
-- ============================================================

CREATE TABLE source_classifications (
    cls_id INTEGER GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,

    cls_src_id INTEGER NOT NULL,
    cls_prm_id INTEGER NOT NULL,

    cls_category VARCHAR,
    cls_importance VARCHAR,
    cls_sentiment VARCHAR,

    cls_should_trigger BOOLEAN NOT NULL DEFAULT FALSE,
    cls_reason TEXT,

    cls_created_at TIMESTAMP NOT NULL DEFAULT NOW(),

    CONSTRAINT fk_source_classifications_source
        FOREIGN KEY (cls_src_id)
        REFERENCES data_sources(src_id),

    CONSTRAINT fk_source_classifications_prompt
        FOREIGN KEY (cls_prm_id)
        REFERENCES prompts(prm_id)
);


-- ============================================================
-- NICHES DE LA CLASSIFICATION
-- ============================================================

CREATE TABLE classification_niches (
    cln_cls_id INTEGER NOT NULL,
    cln_nic_id INTEGER NOT NULL,

    PRIMARY KEY (
        cln_cls_id,
        cln_nic_id
    ),

    CONSTRAINT fk_classification_niches_classification
        FOREIGN KEY (cln_cls_id)
        REFERENCES source_classifications(cls_id)
        ON DELETE CASCADE,

    CONSTRAINT fk_classification_niches_niche
        FOREIGN KEY (cln_nic_id)
        REFERENCES niches(nic_id)
        ON DELETE CASCADE
);


-- ============================================================
-- ACTIFS DE LA CLASSIFICATION
-- ============================================================

CREATE TABLE classification_assets (
    cla_cls_id INTEGER NOT NULL,
    cla_ast_id INTEGER NOT NULL,
    cla_prm_id INTEGER,

    cla_relevance_confidence INTEGER,
    cla_reason TEXT,

    PRIMARY KEY (
        cla_cls_id,
        cla_ast_id
    ),

    CONSTRAINT fk_classification_assets_classification
        FOREIGN KEY (cla_cls_id)
        REFERENCES source_classifications(cls_id),

    CONSTRAINT fk_classification_assets_asset
        FOREIGN KEY (cla_ast_id)
        REFERENCES assets(ast_id),

    CONSTRAINT fk_classification_assets_prompt
        FOREIGN KEY (cla_prm_id)
        REFERENCES prompts(prm_id)
        ON DELETE SET NULL
);


-- ============================================================
-- ANALYSES
-- ============================================================

CREATE TABLE analyses (
    anl_id INTEGER GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,

    anl_prm_id INTEGER NOT NULL,
    anl_cls_id INTEGER,
    anl_prt_id INTEGER,
    anl_ast_id INTEGER,

    anl_trigger_type VARCHAR NOT NULL,
    anl_trigger_reason TEXT,

    anl_response_text TEXT NOT NULL,
    anl_summary TEXT,

    anl_direction VARCHAR,
    anl_market_sentiment VARCHAR,
    anl_confidence INTEGER,
    anl_risk_level VARCHAR,

    anl_timeframe VARCHAR,

    anl_created_at TIMESTAMP NOT NULL DEFAULT NOW(),

    CONSTRAINT fk_analyses_prompt
        FOREIGN KEY (anl_prm_id)
        REFERENCES prompts(prm_id),

    CONSTRAINT fk_analyses_portfolio
        FOREIGN KEY (anl_prt_id)
        REFERENCES portfolios(prt_id),

    CONSTRAINT fk_analyses_classification
        FOREIGN KEY (anl_cls_id)
        REFERENCES source_classifications(cls_id)
        ON DELETE SET NULL,

    CONSTRAINT fk_analyses_asset
        FOREIGN KEY (anl_ast_id)
        REFERENCES assets(ast_id)
);


-- ============================================================
-- ACTIFS ÉVALUÉS PAR LES ANALYSES
-- ============================================================

CREATE TABLE analysis_assets (
    aas_anl_id INTEGER NOT NULL,
    aas_ast_id INTEGER NOT NULL,

    aas_direction VARCHAR,
    aas_confidence INTEGER,
    aas_timeframe VARCHAR,
    aas_reason TEXT,
    aas_price_context JSONB,

    PRIMARY KEY (
        aas_anl_id,
        aas_ast_id
    ),

    CONSTRAINT fk_analysis_assets_analysis
        FOREIGN KEY (aas_anl_id)
        REFERENCES analyses(anl_id)
        ON DELETE CASCADE,

    CONSTRAINT fk_analysis_assets_asset
        FOREIGN KEY (aas_ast_id)
        REFERENCES assets(ast_id)
        ON DELETE CASCADE
);


-- ============================================================
-- SOURCES UTILISÉES PAR LES ANALYSES
-- ============================================================

CREATE TABLE analysis_sources (
    ans_anl_id INTEGER NOT NULL,
    ans_src_id INTEGER NOT NULL,

    PRIMARY KEY (
        ans_anl_id,
        ans_src_id
    ),

    CONSTRAINT fk_analysis_sources_analysis
        FOREIGN KEY (ans_anl_id)
        REFERENCES analyses(anl_id),

    CONSTRAINT fk_analysis_sources_source
        FOREIGN KEY (ans_src_id)
        REFERENCES data_sources(src_id)
);


-- ============================================================
-- ENTRÉES DES ANALYSES
-- ============================================================

CREATE TABLE analysis_inputs (
    inp_anl_id INTEGER NOT NULL,
    inp_src_anl_id INTEGER NOT NULL,

    PRIMARY KEY (
        inp_anl_id,
        inp_src_anl_id
    ),

    CONSTRAINT fk_analysis_inputs_analysis
        FOREIGN KEY (inp_anl_id)
        REFERENCES analyses(anl_id),

    CONSTRAINT fk_analysis_inputs_source_analysis
        FOREIGN KEY (inp_src_anl_id)
        REFERENCES analyses(anl_id)
);


-- ============================================================
-- ANALYSES DE SUIVI DEMANDÉES PAR L'ORCHESTRATEUR
-- ============================================================

CREATE TABLE orchestrator_analysis_jobs (
    oaj_id INTEGER GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
    oaj_ast_id INTEGER NOT NULL,
    oaj_result_anl_id INTEGER,
    oaj_question TEXT NOT NULL,
    oaj_reason TEXT NOT NULL,
    oaj_priority INTEGER NOT NULL,
    oaj_status VARCHAR NOT NULL DEFAULT 'pending',
    oaj_error TEXT,
    oaj_requested_at TIMESTAMPTZ NOT NULL DEFAULT NOW(),
    oaj_started_at TIMESTAMPTZ,
    oaj_completed_at TIMESTAMPTZ,

    CONSTRAINT fk_orchestrator_analysis_jobs_asset
        FOREIGN KEY (oaj_ast_id)
        REFERENCES assets(ast_id),

    CONSTRAINT fk_orchestrator_analysis_jobs_result
        FOREIGN KEY (oaj_result_anl_id)
        REFERENCES analyses(anl_id)
        ON DELETE SET NULL,

    CONSTRAINT chk_orchestrator_analysis_job_status
        CHECK (oaj_status IN ('pending', 'running', 'succeeded', 'failed')),

    CONSTRAINT chk_orchestrator_analysis_job_priority
        CHECK (oaj_priority BETWEEN 1 AND 5)
);

CREATE INDEX idx_orchestrator_analysis_jobs_status_requested
    ON orchestrator_analysis_jobs (oaj_status, oaj_requested_at);


-- ============================================================
-- SIGNAUX
-- ============================================================

CREATE TABLE signals (
    sig_id INTEGER GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,

    sig_anl_id INTEGER NOT NULL,

    sig_prt_id INTEGER,
    sig_ast_id INTEGER NOT NULL,

    sig_action VARCHAR NOT NULL,

    sig_entry_price DECIMAL(18,8),
    sig_stop_loss_price DECIMAL(18,8),
    sig_take_profit_price DECIMAL(18,8),

    sig_confidence INTEGER,
    sig_timeframe VARCHAR,

    sig_status VARCHAR DEFAULT 'active',

    sig_expires_at TIMESTAMP,
    sig_created_at TIMESTAMP NOT NULL DEFAULT NOW(),

    CONSTRAINT fk_signals_analysis
        FOREIGN KEY (sig_anl_id)
        REFERENCES analyses(anl_id),

    CONSTRAINT fk_signals_portfolio
        FOREIGN KEY (sig_prt_id)
        REFERENCES portfolios(prt_id),

    CONSTRAINT fk_signals_asset
        FOREIGN KEY (sig_ast_id)
        REFERENCES assets(ast_id)
);


-- ============================================================
-- PORTFOLIO STRATEGISTS AND MARKET OPPORTUNITY EVENTS
-- ============================================================

CREATE TABLE portfolio_strategists (
    pst_id INTEGER GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
    pst_prt_id INTEGER NOT NULL UNIQUE
        REFERENCES portfolios(prt_id) ON DELETE CASCADE,
    pst_status VARCHAR NOT NULL DEFAULT 'active',
    pst_instructions TEXT,
    pst_last_signal_id INTEGER NOT NULL DEFAULT 0,
    pst_last_full_review_at TIMESTAMPTZ,
    pst_next_full_review_at TIMESTAMPTZ NOT NULL DEFAULT NOW(),
    pst_last_summary TEXT,
    pst_created_at TIMESTAMPTZ NOT NULL DEFAULT NOW(),
    pst_updated_at TIMESTAMPTZ NOT NULL DEFAULT NOW(),
    CONSTRAINT chk_portfolio_strategist_status
        CHECK (pst_status IN ('active', 'paused'))
);

CREATE INDEX idx_portfolio_strategists_due
    ON portfolio_strategists (pst_status, pst_next_full_review_at);

CREATE TABLE market_opportunity_events (
    moe_id INTEGER GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
    moe_ast_id INTEGER NOT NULL REFERENCES assets(ast_id) ON DELETE CASCADE,
    moe_result_anl_id INTEGER REFERENCES analyses(anl_id) ON DELETE SET NULL,
    moe_event_type VARCHAR NOT NULL,
    moe_price_before NUMERIC(18,8) NOT NULL,
    moe_price_after NUMERIC(18,8) NOT NULL,
    moe_change_pct NUMERIC(10,4) NOT NULL,
    moe_window_seconds INTEGER NOT NULL,
    moe_reason TEXT NOT NULL,
    moe_status VARCHAR NOT NULL DEFAULT 'detected',
    moe_error TEXT,
    moe_detected_at TIMESTAMPTZ NOT NULL DEFAULT NOW(),
    moe_analyzed_at TIMESTAMPTZ,
    CONSTRAINT chk_market_opportunity_event_type
        CHECK (moe_event_type IN ('price_rise', 'price_drop')),
    CONSTRAINT chk_market_opportunity_event_status
        CHECK (moe_status IN ('detected', 'analyzing', 'analyzed', 'notified', 'failed'))
);

CREATE INDEX idx_market_opportunity_events_status
    ON market_opportunity_events (moe_status, moe_detected_at);

CREATE TABLE portfolio_strategist_runs (
    psr_id INTEGER GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
    psr_pst_id INTEGER NOT NULL
        REFERENCES portfolio_strategists(pst_id) ON DELETE CASCADE,
    psr_ast_id INTEGER REFERENCES assets(ast_id) ON DELETE SET NULL,
    psr_sig_id INTEGER REFERENCES signals(sig_id) ON DELETE SET NULL,
    psr_moe_id INTEGER REFERENCES market_opportunity_events(moe_id) ON DELETE SET NULL,
    psr_result_anl_id INTEGER REFERENCES analyses(anl_id) ON DELETE SET NULL,
    psr_prm_id INTEGER REFERENCES prompts(prm_id) ON DELETE SET NULL,
    psr_review_type VARCHAR NOT NULL,
    psr_status VARCHAR NOT NULL DEFAULT 'pending',
    psr_priority INTEGER NOT NULL DEFAULT 3,
    psr_reason TEXT NOT NULL,
    psr_decision JSONB,
    psr_error TEXT,
    psr_created_at TIMESTAMPTZ NOT NULL DEFAULT NOW(),
    psr_started_at TIMESTAMPTZ,
    psr_completed_at TIMESTAMPTZ,
    CONSTRAINT chk_portfolio_strategist_run_type
        CHECK (psr_review_type IN ('targeted_signal', 'targeted_price', 'full')),
    CONSTRAINT chk_portfolio_strategist_run_status
        CHECK (psr_status IN ('pending', 'running', 'succeeded', 'failed', 'merged')),
    CONSTRAINT chk_portfolio_strategist_run_priority
        CHECK (psr_priority BETWEEN 1 AND 5)
);

CREATE INDEX idx_portfolio_strategist_runs_pending
    ON portfolio_strategist_runs (psr_status, psr_priority DESC, psr_created_at);
CREATE UNIQUE INDEX uq_portfolio_strategist_run_signal
    ON portfolio_strategist_runs (psr_pst_id, psr_sig_id)
    WHERE psr_sig_id IS NOT NULL;
CREATE UNIQUE INDEX uq_portfolio_strategist_run_event
    ON portfolio_strategist_runs (psr_pst_id, psr_moe_id)
    WHERE psr_moe_id IS NOT NULL;


COMMIT;
